import json
from collections import Counter

orig = [json.loads(l) for l in open('data/final_v2/train.jsonl')]
scram = [json.loads(l) for l in open('data/final_v2/train_scrambled.jsonl')]

# Check distribution
def get_dist(data):
    c = Counter()
    for conv in data:
        for t in conv['turns']:
            if t.get('role') == 'user' and 'persuasion_strategy' in t:
                c[t['persuasion_strategy']] += 1
    return c

orig_dist = get_dist(orig)
scram_dist = get_dist(scram)
print('Original distribution:', dict(sorted(orig_dist.items())))
print('Scrambled distribution:', dict(sorted(scram_dist.items())))
print('Distributions match:', orig_dist == scram_dist)

# Check change rate for jailbreak
changed = 0
total_jb = 0
for o, s in zip(orig, scram):
    if o.get('label') != 'jailbreak':
        continue
    for ot, st in zip(o['turns'], s['turns']):
        if ot.get('role') == 'user' and 'persuasion_strategy' in ot:
            total_jb += 1
            if ot['persuasion_strategy'] != st['persuasion_strategy']:
                changed += 1

print(f'Jailbreak turns changed: {changed}/{total_jb} = {changed/total_jb*100:.1f}%')

# Check benign unchanged
benign_changed = 0
total_benign = 0
for o, s in zip(orig, scram):
    if o.get('label') != 'benign':
        continue
    for ot, st in zip(o['turns'], s['turns']):
        if ot.get('role') == 'user' and 'persuasion_strategy' in ot:
            total_benign += 1
            if ot['persuasion_strategy'] != st['persuasion_strategy']:
                benign_changed += 1

print(f'Benign turns changed: {benign_changed}/{total_benign} (should be 0)')
